// ESP-IDF 5.x; INMP441 L/R selects the left mono slot.
#include <stdio.h>
#include "driver/i2s_std.h"
#include "esp_check.h"

void app_main(void) {
  i2s_chan_handle_t rx_handle;
  const i2s_chan_config_t channel_config =
      I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
  ESP_ERROR_CHECK(i2s_new_channel(&channel_config, NULL, &rx_handle));

  const i2s_std_config_t standard_config = {
      .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(16000),
      .slot_cfg = I2S_STD_MSB_SLOT_DEFAULT_CONFIG(
          I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_MONO),
      .gpio_cfg = {
          .mclk = I2S_GPIO_UNUSED,
          .bclk = GPIO_NUM_26,
          .ws = GPIO_NUM_25,
          .dout = I2S_GPIO_UNUSED,
          .din = GPIO_NUM_32,
      },
  };
  ESP_ERROR_CHECK(i2s_channel_init_std_mode(rx_handle, &standard_config));
  ESP_ERROR_CHECK(i2s_channel_enable(rx_handle));

  int32_t samples[128];
  size_t bytes_read;
  while (true) {
    ESP_ERROR_CHECK(i2s_channel_read(
        rx_handle, samples, sizeof(samples), &bytes_read, portMAX_DELAY));
    for (size_t i = 0; i < bytes_read / sizeof(samples[0]); ++i) {
      printf("%ld\n", (long)(samples[i] >> 8));
    }
  }
}
